package com.lamggm.rospocket;
import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31,qualifiers="w1000dp-h700dp") @LooperMode(LooperMode.Mode.PAUSED)
public class LocationOperatorTest {
 final ConnectionActivityTest f=new ConnectionActivityTest();
 @Before public void setup()throws Exception{f.setup();f.controller.visible();f.paint();f.a.findViewById(R.id.nav_location).performClick();}
 @After public void cleanup()throws Exception{f.cleanup();}
 View v(String tag){return f.a.getWindow().getDecorView().findViewWithTag(tag);}
 @Test public void changingMapFrameDoesNotRetainThePriorTfDiagnostic()throws Exception{LocationPanel p=(LocationPanel)v("location-page");v("location-observe").performClick();LocationPanel.Request r=p.desired();java.lang.reflect.Field d=LocationPanel.class.getDeclaredField("decoder");d.setAccessible(true);java.util.concurrent.ExecutorService worker=(java.util.concurrent.ExecutorService)d.get(p);p.accept(r,p.epoch(),MapPacketTest.packet(MapPacketTest.meta(),new byte[]{-1,0,50,100}),()->true);worker.submit(()->{}).get();f.paint();double[] m=RobotDescription.identity();p.pose(r,p.epoch(),p.map(),new RobotTf.Pose(true,"OLD_FRAME_TF",123456789L,1,java.util.Collections.singletonMap("base_link",m),System.nanoTime()+1000000000L));p.accept(r,p.epoch(),MapPacketTest.packet(MapPacketTest.meta().put("frameId","odom"),new byte[]{-1,0,50,100}),()->true);worker.submit(()->{}).get();f.paint();v("location-diagnostics-toggle").performClick();String text=ConnectionActivityTest.textOf(v("location-diagnostics"));assertFalse(text,text.contains("OLD_FRAME_TF")||text.contains("123456789 ns"));}
 @Test public void observedTrailIsBoundedBrokenOnGapsAndCanBeDisabledPersistently()throws Exception{CheckBox toggle=(CheckBox)v("location-trail");assertNotNull(toggle);LocationMapView s=(LocationMapView)v("location-surface");s.map(new SensorPacket(MapPacketTest.packet(MapPacketTest.meta(),new byte[]{-1,0,50,100})).decode().map);long d=System.nanoTime()+10000000000L;s.pose(1,2,0,d);s.pose(2,2,0,d);assertEquals(2,LocationMapView.class.getDeclaredMethod("trailSize").invoke(s));s.clearPose();s.pose(3,3,0,d);assertEquals(2,LocationMapView.class.getDeclaredMethod("trailSegments").invoke(s));for(int i=0;i<400;i++)s.pose(i,2,0,d);assertTrue((Integer)LocationMapView.class.getDeclaredMethod("trailSize").invoke(s)<=256);toggle.performClick();assertEquals(0,LocationMapView.class.getDeclaredMethod("trailSize").invoke(s));LocationPanel another=new LocationPanel(f.a);try{assertFalse(((CheckBox)another.findViewWithTag("location-trail")).isChecked());}finally{another.dispose();}s.pose(5,6,0,d);assertEquals(0,LocationMapView.class.getDeclaredMethod("trailSize").invoke(s));}
 @Test public void diagnosticsUseMapOffersNotWatchCompatibilityAndKeepUnknownExplicit()throws Exception{v("location-observe").performClick();View toggle=v("location-diagnostics-toggle");assertNotNull(toggle);org.json.JSONObject qos=new org.json.JSONObject().put("reliability","best_effort").put("durability","volatile");org.json.JSONObject endpoint=new org.json.JSONObject().put("writer",true).put("qos",qos).put("compatibility",new org.json.JSONObject().put("state","compatible"));org.json.JSONObject topic=new org.json.JSONObject().put("wireName","rt/map").put("wireType",MapGrid.TYPE).put("endpoints",new org.json.JSONArray().put(endpoint));f.bridge.snapshot=new org.json.JSONObject(f.bridge.snapshot).put("topics",new org.json.JSONArray().put(topic)).toString();f.tick();f.paint();toggle.performClick();String text=ConnectionActivityTest.textOf(v("location-diagnostics"));assertTrue(text,text.contains("Oferta incompatível observada")&&text.contains("best_effort"));endpoint.remove("qos");f.bridge.snapshot=new org.json.JSONObject(f.bridge.snapshot).put("topics",new org.json.JSONArray().put(topic)).toString();f.set("lastUi",0L);f.tick();f.paint();text=ConnectionActivityTest.textOf(v("location-diagnostics"));assertTrue(text,text.contains("QoS ofertado desconhecido"));assertFalse(text,text.contains("Oferta incompatível observada"));}
 @Test public void livePoseUsesMonotonicReceptionAgeInsteadOfRobotEpochNotation()throws Exception{LocationPanel p=(LocationPanel)v("location-page");v("location-observe").performClick();LocationPanel.Request r=p.desired();p.accept(r,p.epoch(),MapPacketTest.packet(MapPacketTest.meta(),new byte[]{-1,0,50,100}),()->true);java.lang.reflect.Field d=LocationPanel.class.getDeclaredField("decoder");d.setAccessible(true);((java.util.concurrent.ExecutorService)d.get(p)).submit(()->{}).get(5,java.util.concurrent.TimeUnit.SECONDS);f.paint();double[] m=RobotDescription.identity();m[3]=1.05;m[7]=2.05;java.util.Map<String,double[]> transforms=new java.util.HashMap<>();transforms.put("base_link",m);p.pose(r,p.epoch(),p.map(),new RobotTf.Pose(true,"TF observado",1794385920514760000L,1,transforms,System.nanoTime()+1500000000L));String text=ConnectionActivityTest.textOf(v("location-pose"));assertTrue(text,text.contains("Pose atual")&&text.contains("ms"));assertFalse(text.contains("E9"));assertFalse(text.contains("t="));}
 @Test public void technicalSourcesAreCollapsedAndMapDoesNotConsumeTheWholeTablet(){View toggle=v("location-settings-toggle");assertNotNull(toggle);assertEquals(View.GONE,v("location-settings").getVisibility());toggle.performClick();assertEquals(View.VISIBLE,v("location-settings").getVisibility());toggle.performClick();assertEquals(View.GONE,v("location-settings").getVisibility());float d=f.a.getResources().getDisplayMetrics().density;assertTrue(v("location-surface").getLayoutParams().height<=420*d);}
}
